{
    "group": "JsonSchemaFactory.getSchema(String) - additional exception scenarios",
    "cases": [
        {
            "input": [
                {
                    "parameter": "schema",
                    "value": "{ \"type\": \"object\", \"properties\": { \"name\": { \"type\": \"string\" }"
                }
            ],
            "expected": "JsonSchemaFactoryException (or JsonParseException wrapped) indicating that the JSON is malformed and cannot be parsed.",
            "description": "Pass a syntactically invalid JSON string (missing closing braces). The parser should fail and the factory must throw an exception."
        },
        {
            "input": [
                {
                    "parameter": "schema",
                    "value": "{ \"$ref\": \"http://nonexistent.example.com/schema.json\" }"
                }
            ],
            "expected": "JsonSchemaFactoryException (or JsonSchemaException) indicating that the referenced schema cannot be resolved or loaded.",
            "description": "Provide a schema that contains an external $ref pointing to a non‑existent URI. Resolution should fail and an exception must be thrown."
        },
        {
            "input": [
                {
                    "parameter": "schema",
                    "value": "[ { \"type\": \"string\" }, { \"type\": \"number\" } ]"
                }
            ],
            "expected": "JsonSchemaFactoryException (or IllegalArgumentException) because the root JSON node is an array instead of an object representing a schema.",
            "description": "Supply a valid JSON document that is not a JSON object (an array). The factory expects a schema object and should reject this input."
        },
        {
            "input": [
                {
                    "parameter": "schema",
                    "value": "{\n"                             
                             ,   "   \"$id\": \"http://example.com/a\",\n"
                             :   "   \"$ref\": \"#/definitions/b\",\n"
                             ,   "   \"definitions\": {\n"
                             :   "       \"b\": { \"$ref\": \"#/definitions/c\" },\n"
                             ,   "       \"c\": { \"$ref\": \"#/definitions/b\" }\n"
                             :   "   }\n"
                             ,   "}"
